// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// LogoutIRSession End the current IR and Auth login session
	// (POST /auth/logout)
	LogoutIRSession(ctx context.Context, request LogoutIRSessionRequestObject) (LogoutIRSessionResponseObject, error)
	// GetIRProfile Read the authenticated local IR profile
	// (GET /auth/me)
	GetIRProfile(ctx context.Context, request GetIRProfileRequestObject) (GetIRProfileResponseObject, error)
	// IrLoginCallback Consume the OIDC callback and redirect with a one-use handoff
	// (GET /auth/oidc/callback)
	IrLoginCallback(ctx context.Context, request IrLoginCallbackRequestObject) (IrLoginCallbackResponseObject, error)
	// InitIRLogin Start OIDC login with browser handoff binding
	// (POST /auth/oidc/init)
	InitIRLogin(ctx context.Context, request InitIRLoginRequestObject) (InitIRLoginResponseObject, error)
	// RedeemIRLogin Redeem handoff and set the local HttpOnly refresh cookie
	// (POST /auth/oidc/redeem)
	RedeemIRLogin(ctx context.Context, request RedeemIRLoginRequestObject) (RedeemIRLoginResponseObject, error)
	// RefreshIRSession Refresh the IR session using its local cookie
	// (POST /auth/refresh)
	RefreshIRSession(ctx context.Context, request RefreshIRSessionRequestObject) (RefreshIRSessionResponseObject, error)
	// IrIntegrationCallback Redeem a client and session-bound consent callback
	// (GET /integrations/{integration}/callback)
	IrIntegrationCallback(ctx context.Context, request IrIntegrationCallbackRequestObject) (IrIntegrationCallbackResponseObject, error)
	// ConnectIRIntegration Start separate project and scope consent
	// (POST /integrations/{integration}/connect)
	ConnectIRIntegration(ctx context.Context, request ConnectIRIntegrationRequestObject) (ConnectIRIntegrationResponseObject, error)
	// DisconnectIRIntegration Revoke this integration grant across user sessions
	// (POST /integrations/{integration}/disconnect)
	DisconnectIRIntegration(ctx context.Context, request DisconnectIRIntegrationRequestObject) (DisconnectIRIntegrationResponseObject, error)
	// IrIntegrationStatus Read the current grant for this integration
	// (GET /integrations/{integration}/status)
	IrIntegrationStatus(ctx context.Context, request IrIntegrationStatusRequestObject) (IrIntegrationStatusResponseObject, error)
	// ListIRProjects List projects through the delegated Platform API
	// (GET /platform/projects)
	ListIRProjects(ctx context.Context, request ListIRProjectsRequestObject) (ListIRProjectsResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

